sqlGroup.select:
select a.id, a.`name`, a.start_address, a.end_address, a.mileage, a.start_mileage, a.status, date_format(a.start_time,'%Y-%m-%d %H:%i:%s') as start_time, date_format(a.end_time,'%Y-%m-%d %H:%i:%s') as end_time, date_format(a.created_time,'%Y-%m-%d %H:%i:%s') as created_time, cs.`name` AS createdStaffName, ar.name as areaName, a.district
from jml_mileage_certification a left join jml_staff cs ON a.created_staff_id = cs.id left join jml_area ar on a.area_code = ar.area_code
and a.status = #{status}
and a.created_staff_id = #{staffId}
order by a.created_time desc
